(() => {
  const catalan = {"CMV GRUP | Construcción y reformas integrales": "CMV GRUP | Construcció i reformes integrals", "CONSTRUCCIÓN · REFORMAS INTEGRALES": "CONSTRUCCIÓ · REFORMES INTEGRALS", "Quiénes somos": "Qui som", "Nuestros servicios": "Els nostres serveis", "Cómo trabajamos": "Com treballem", "Hablemos": "Parlem", "Hablar por WhatsApp": "Parlar per WhatsApp", "Construimos espacios para vivirlos mejor.": "Construïm espais per viure-hi millor.", "Obra nueva y reformas integrales para viviendas, negocios y comunidades. Cada proyecto, con atención al detalle y un equipo comprometido de principio a fin.": "Obra nova i reformes integrals per a habitatges, negocis i comunitats. Cada projecte, amb atenció al detall i un equip compromès de principi a fi.", "Cuéntanos tu proyecto": "Explica’ns el teu projecte", "Ver servicios": "Veure serveis", "Imagen de inspiración": "Imatge d’inspiració", "Más de 40 años": "Més de 40 anys", "de experiencia en construcción": "d’experiència en construcció", "De principio a fin": "De principi a fi", "un interlocutor para tu proyecto": "un interlocutor per al teu projecte", "A medida": "A mida", "soluciones para cada espacio y necesidad": "solucions per a cada espai i necessitat", "El oficio de construir, con una mirada actual.": "L’ofici de construir, amb una mirada actual.", "En CMV GRUP abordamos cada obra con seriedad, planificación y respeto por los espacios de nuestros clientes. Escuchamos lo que necesitas, estudiamos las posibilidades y cuidamos la ejecución hasta el último detalle.": "A CMV GRUP abordem cada obra amb serietat, planificació i respecte pels espais dels nostres clients. Escoltem el que necessites, estudiem les possibilitats i cuidem l’execució fins a l’últim detall.", "Trabajamos en proyectos residenciales y comerciales, desde una reforma completa hasta intervenciones en edificios y fachadas.": "Treballem en projectes residencials i comercials, des d’una reforma completa fins a intervencions en edificis i façanes.", "Solicitar una consulta": "Sol·licitar una consulta", "Una solución completa para cada proyecto.": "Una solució completa per a cada projecte.", "Adaptamos el alcance a tu inmueble, tus prioridades y el resultado que buscas.": "Adaptem l’abast al teu immoble, les teves prioritats i el resultat que busques.", "Reformas integrales de viviendas": "Reformes integrals d’habitatges", "Redistribución, renovación de instalaciones, acabados, cocinas y baños para transformar tu hogar.": "Redistribució, renovació d’instal·lacions, acabats, cuines i banys per transformar la teva llar.", "Ampliar": "Ampliar", "Imágenes de inspiración": "Imatges d’inspiració", "Ver portfolio": "Veure portafolis", "Casas y obra nueva": "Cases i obra nova", "Construcción y ampliaciones con atención a la calidad de ejecución y la coordinación de cada fase.": "Construcció i ampliacions amb atenció a la qualitat de l’execució i la coordinació de cada fase.", "Locales comerciales": "Locals comercials", "Adecuación y reforma de espacios para que tu negocio funcione y transmita su identidad.": "Adequació i reforma d’espais perquè el teu negoci funcioni i transmeti la seva identitat.", "Oficinas": "Oficines", "Espacios de trabajo cómodos, prácticos y preparados para las necesidades del equipo.": "Espais de treball còmodes, pràctics i preparats per a les necessitats de l’equip.", "Edificios y comunidades": "Edificis i comunitats", "Actuaciones de rehabilitación, conservación y mejora de zonas comunes y elementos constructivos.": "Actuacions de rehabilitació, conservació i millora de zones comunes i elements constructius.", "Fachadas": "Façanes", "Reparación y renovación de revestimientos y elementos exteriores, según las necesidades de cada edificio.": "Reparació i renovació de revestiments i elements exteriors, segons les necessitats de cada edifici.", "Claridad en cada paso de la obra.": "Claredat en cada pas de l’obra.", "Una conversación inicial nos permite entender el espacio, el alcance y tus prioridades.": "Una conversa inicial ens permet entendre l’espai, l’abast i les teves prioritats.", "Nos cuentas tu idea": "Ens expliques la teva idea", "Escuchamos tus objetivos y revisamos las necesidades del inmueble.": "Escoltem els teus objectius i revisem les necessitats de l’immoble.", "Definimos el alcance": "Definim l’abast", "Valoramos los trabajos, materiales y fases necesarias para el proyecto.": "Valorem els treballs, materials i fases necessàries per al projecte.", "Ejecutamos con cuidado": "Executem amb cura", "Coordinamos la obra y prestamos atención a los detalles de ejecución.": "Coordinem l’obra i prestem atenció als detalls de l’execució.", "Hablemos de tu proyecto": "Parlem del teu projecte", "Tu próximo proyecto empieza con una conversación.": "El teu proper projecte comença amb una conversa.", "Cuéntanos qué inmueble quieres construir o reformar, dónde está y qué necesitas. Te responderemos por WhatsApp para conocer los detalles.": "Explica’ns quin immoble vols construir o reformar, on és i què necessites. Et respondrem per WhatsApp per conèixer-ne els detalls.", "Maresme y alrededores · Barcelona · Girona": "Maresme i voltants · Barcelona · Girona", "Tu nombre": "El teu nom", "Ubicación de la obra": "Ubicació de l’obra", "Tipo de proyecto": "Tipus de projecte", "Selecciona una opción": "Selecciona una opció", "Reforma integral de vivienda": "Reforma integral d’habitatge", "Casa u obra nueva": "Casa o obra nova", "Local comercial": "Local comercial", "Oficina": "Oficina", "Edificio o comunidad": "Edifici o comunitat", "Fachada": "Façana", "Otro": "Altres", "¿Qué necesitas?": "Què necessites?", "Enviar consulta por WhatsApp": "Enviar consulta per WhatsApp", "Al pulsar, se abrirá WhatsApp con tu mensaje preparado para enviarlo.": "En prémer, s’obrirà WhatsApp amb el teu missatge preparat per enviar-lo.", "Construcción y reformas integrales": "Construcció i reformes integrals", "Cerrar": "Tancar", "Anterior": "Anterior", "Siguiente": "Següent", "Imagen de inspiración. Consulta por WhatsApp para hablar de tu proyecto.": "Imatge d’inspiració. Consulta per WhatsApp per parlar del teu projecte.", "Por ejemplo, Mataró": "Per exemple, Mataró", "Descríbenos brevemente el trabajo": "Descriu-nos breument el treball", "Abrir menú": "Obrir menú", "Cerrar menú": "Tancar menú", "Navegación principal": "Navegació principal", "Imagen anterior": "Imatge anterior", "Imagen siguiente": "Imatge següent", "Imágenes de la categoría": "Imatges de la categoria", "CMV GRUP, construcción y reformas integrales, inicio": "CMV GRUP, construcció i reformes integrals, inici", "Hola, quiero consultar sobre una obra": "Hola, voldria consultar sobre una obra", "Hola, quiero hablar sobre mi proyecto": "Hola, voldria parlar del meu projecte", "Contacto": "Contacte", "Profesionales de cada oficio": "Professionals de cada ofici", "Somos un grupo de constructores con personal cualificado en cada especialidad. Coordinamos los distintos oficios para dar una respuesta integral a tu proyecto.": "Som un grup de constructors amb personal qualificat en cada especialitat. Coordinem els diferents oficis per donar una resposta integral al teu projecte.", "Albañilería y mampostería": "Paleteria i maçoneria", "Pladur y tabiquería": "Pladur i envans", "Electricidad": "Electricitat", "Carpintería": "Fusteria", "Fontanería": "Fontaneria", "Pintura y revestimientos": "Pintura i revestiments", "CMV GRUP, inicio": "CMV GRUP, inici", "CMV Grup, logo de la empresa con ladrillos": "CMV Grup, logotip de l’empresa amb maons", "Saltar al contenido": "Salta al contingut", "Menú": "Menú", "Imagen": "Imatge", "Pie de página": "Peu de pàgina", "Dos hombres sonrientes junto a una furgoneta con el capó abierto en un taller": "Dos homes somrients al costat d’una furgoneta amb el capó obert en un taller"};
  const WHATSAPP = "34615037545";
  const metaCa = "CMV GRUP: construcció i reformes integrals d’habitatges, locals, oficines, edificis i façanes al Maresme i voltants.";
  const categories = ["Reformas integrales de viviendas", "Casas y obra nueva", "Locales comerciales", "Oficinas", "Edificios y comunidades"];
  let lang = "es";

  const tr = (text) => {
    if (lang !== "ca") return text;
    if (catalan[text]) return catalan[text];
    let out = text;
    categories.forEach((key) => { out = out.replace(key, catalan[key]); });
    return out
      .replace(/Referencia visual de /g, "Referència visual de ")
      .replace(/Imagen de inspiración: /g, "Imatge d’inspiració: ")
      .replace(/Ampliar imagen de inspiración /g, "Ampliar imatge d’inspiració ")
      .replace(/Ver imagen /g, "Veure imatge ")
      .replace(/reformas integrales de viviendas/g, "reformes integrals d’habitatges")
      .replace(/casas y obra nueva/g, "cases i obra nova")
      .replace(/locales comerciales/g, "locals comercials")
      .replace(/oficinas/g, "oficines")
      .replace(/edificios y comunidades/g, "edificis i comunitats");
  };

  document.getElementById("year").textContent = new Date().getFullYear();

  /* ---------- Barra: compacta al pasar el banner ---------- */
  const bar = document.getElementById("bar");
  /* ---------- Menú móvil ---------- */
  const menu = document.getElementById("menuToggle");
  const links = document.getElementById("barLinks");
  const setMenu = (open) => {
    links.classList.toggle("open", open);
    menu.setAttribute("aria-expanded", String(open));
    menu.setAttribute("aria-label", tr(open ? "Cerrar menú" : "Abrir menú"));
  };
  menu.addEventListener("click", () => setMenu(menu.getAttribute("aria-expanded") !== "true"));
  links.addEventListener("click", (e) => { if (e.target.closest("a")) setMenu(false); });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && links.classList.contains("open")) { setMenu(false); menu.focus(); }
  });
  document.addEventListener("click", (e) => {
    if (links.classList.contains("open") && !bar.contains(e.target)) setMenu(false);
  });

  /* ---------- Sección activa ---------- */
  const navLinks = [...links.querySelectorAll("a")];
  const sectionObserver = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      navLinks.forEach((a) => a.setAttribute("aria-current", String(a.getAttribute("href") === "#" + entry.target.id)));
    });
  }, { rootMargin: "-45% 0px -50% 0px" });
  navLinks.forEach((a) => {
    const section = document.querySelector(a.getAttribute("href"));
    if (section) sectionObserver.observe(section);
  });

  /* ---------- Formulario → WhatsApp ---------- */
  const form = document.getElementById("contactForm");
  const errorText = {
    es: { valueMissing: "Este campo es obligatorio.", select: "Elige el tipo de proyecto." },
    ca: { valueMissing: "Aquest camp és obligatori.", select: "Tria el tipus de projecte." },
  };
  const showError = (field) => {
    const wrap = field.closest(".field");
    let msg = wrap.querySelector(".field-error");
    if (field.validity.valid) {
      wrap.classList.remove("has-error");
      field.removeAttribute("aria-invalid");
      if (msg) msg.remove();
      return true;
    }
    if (!msg) {
      msg = document.createElement("span");
      msg.className = "field-error";
      msg.id = field.id + "-error";
      wrap.append(msg);
      field.setAttribute("aria-describedby", msg.id);
    }
    msg.textContent = errorText[lang][field.tagName === "SELECT" ? "select" : "valueMissing"];
    wrap.classList.add("has-error");
    field.setAttribute("aria-invalid", "true");
    return false;
  };
  form.querySelectorAll("input, select, textarea").forEach((field) => {
    field.addEventListener("input", () => { if (field.closest(".has-error")) showError(field); });
    field.addEventListener("change", () => { if (field.closest(".has-error")) showError(field); });
  });
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const fields = [...form.querySelectorAll("input, select, textarea")];
    const invalid = fields.filter((f) => !showError(f));
    if (invalid.length) { invalid[0].focus(); return; }
    const data = new FormData(form);
    const type = form.querySelector("#type").selectedOptions[0].textContent;
    const msg = lang === "ca"
      ? `Hola, soc ${data.get("name")}.\nUbicació de l’obra: ${data.get("place")}\nTipus de projecte: ${type}\nNecessito: ${data.get("message")}`
      : `Hola, soy ${data.get("name")}.\nUbicación de la obra: ${data.get("place")}\nTipo de proyecto: ${type}\nNecesito: ${data.get("message")}`;
    window.open(`https://wa.me/${WHATSAPP}?text=${encodeURIComponent(msg)}`, "_blank", "noopener");
  });

  /* ---------- Galería por servicio ---------- */
  const gallery = document.getElementById("serviceGallery");
  const galleryImage = document.getElementById("galleryImage");
  const galleryThumbs = document.getElementById("galleryThumbs");
  const prev = document.getElementById("galleryPrev");
  const next = document.getElementById("galleryNext");
  let activeCard = null, activeImages = [], activeIndex = 0, lastFocus = null;

  const renderImage = () => {
    const source = activeImages[activeIndex];
    galleryImage.src = source.dataset.image;
    galleryImage.alt = tr("Imagen de inspiración: ") + tr(source.dataset.category);
    document.getElementById("galleryCount").textContent = `${activeIndex + 1} / ${activeImages.length}`;
    prev.disabled = activeIndex === 0;
    next.disabled = activeIndex === activeImages.length - 1;
    galleryThumbs.querySelectorAll("button").forEach((b, i) => b.setAttribute("aria-current", String(i === activeIndex)));
  };

  const openPortfolio = (card, index = 0) => {
    activeCard = card;
    activeImages = [...card.querySelectorAll(".service-photo")];
    activeIndex = index;
    document.getElementById("galleryTitle").textContent = card.querySelector("h3").textContent;
    galleryThumbs.replaceChildren();
    activeImages.forEach((source, i) => {
      const b = document.createElement("button");
      b.type = "button";
      b.setAttribute("aria-label", tr("Ver imagen ") + (i + 1));
      const img = document.createElement("img");
      img.src = source.querySelector("img").src;
      img.alt = "";
      b.append(img);
      b.addEventListener("click", () => { activeIndex = i; renderImage(); });
      galleryThumbs.append(b);
    });
    renderImage();
    if (!gallery.open) { lastFocus = document.activeElement; gallery.showModal(); }
  };

  document.querySelectorAll(".service[data-portfolio]").forEach((card) => {
    card.querySelector(".portfolio-link").addEventListener("click", (e) => {
      e.preventDefault();
      history.replaceState(null, "", "#portfolio-" + card.dataset.portfolio);
      openPortfolio(card);
    });
    card.querySelectorAll(".service-photo").forEach((button, i) => button.addEventListener("click", () => openPortfolio(card, i)));
  });
  prev.addEventListener("click", () => { if (activeIndex > 0) { activeIndex--; renderImage(); } });
  next.addEventListener("click", () => { if (activeIndex < activeImages.length - 1) { activeIndex++; renderImage(); } });
  gallery.addEventListener("keydown", (e) => {
    if (e.key === "ArrowLeft") { e.preventDefault(); prev.click(); }
    if (e.key === "ArrowRight") { e.preventDefault(); next.click(); }
  });
  gallery.querySelector(".gallery-close").addEventListener("click", () => gallery.close());
  gallery.addEventListener("close", () => {
    if (location.hash.startsWith("#portfolio-")) history.replaceState(null, "", "#servicios");
    if (lastFocus) lastFocus.focus();
  });
  gallery.addEventListener("click", (e) => {
    if (e.target !== gallery) return;
    const r = gallery.getBoundingClientRect();
    if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) gallery.close();
  });
  const openHashPortfolio = () => {
    const slug = location.hash.replace("#portfolio-", "");
    const card = document.querySelector(`.service[data-portfolio="${CSS.escape(slug)}"]`);
    if (card) openPortfolio(card);
  };
  window.addEventListener("hashchange", openHashPortfolio);
  openHashPortfolio();

  /* ---------- Idioma ES / CA ---------- */
  const textOriginals = new Map();
  const attrOriginals = [];
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
    acceptNode: (node) => node.parentElement.closest("script, style, .lang") ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT,
  });
  while (walker.nextNode()) {
    const n = walker.currentNode;
    if (n.textContent.trim()) textOriginals.set(n, n.textContent);
  }
  textOriginals.set(document.querySelector("title").firstChild, document.title);
  document.querySelectorAll('[alt], [aria-label], [placeholder], meta[name="description"], a[href*="wa.me"]').forEach((el) => {
    if (el.closest(".lang") || el.id === "menuToggle") return;
    ["alt", "aria-label", "placeholder", "content", "href"].forEach((attr) => {
      if (el.hasAttribute(attr)) attrOriginals.push([el, attr, el.getAttribute(attr)]);
    });
  });

  const applyLanguage = (value) => {
    lang = value === "ca" ? "ca" : "es";
    document.documentElement.lang = lang;
    const button = document.getElementById("siteLanguage");
    button.setAttribute("aria-label", lang === "ca" ? "Català. Canviar a castellà" : "Español. Cambiar a catalán");
    button.title = lang === "ca" ? "Català · Canviar a castellà" : "Español · Cambiar a catalán";
    document.getElementById("languageName").textContent = lang.toUpperCase();
    textOriginals.forEach((original, node) => { node.textContent = original.replace(original.trim(), tr(original.trim())); });
    attrOriginals.forEach(([el, attr, original]) => {
      let v = tr(original);
      if (attr === "content" && el.tagName === "META" && lang === "ca") v = metaCa;
      if (attr === "href" && original.includes("wa.me")) {
        const url = new URL(original);
        if (url.searchParams.has("text")) url.searchParams.set("text", tr(url.searchParams.get("text")));
        v = url.href;
      }
      el.setAttribute(attr, v);
    });
    menu.setAttribute("aria-label", tr(menu.getAttribute("aria-expanded") === "true" ? "Cerrar menú" : "Abrir menú"));
    form.querySelectorAll(".has-error input, .has-error select, .has-error textarea").forEach(showError);
    if (gallery.open && activeCard) {
      document.getElementById("galleryTitle").textContent = activeCard.querySelector("h3").textContent;
      renderImage();
    }
    try { localStorage.setItem("cmv-language", lang); } catch (e) { /* almacenamiento no disponible */ }
  };
  document.getElementById("siteLanguage").addEventListener("click", () => applyLanguage(lang === "es" ? "ca" : "es"));
  let saved = "es";
  try { saved = localStorage.getItem("cmv-language") || "es"; } catch (e) { /* almacenamiento no disponible */ }
  if (saved === "ca") applyLanguage("ca");
})();
